-- BIS SIH26107 PHASE 4 - Supabase PostgreSQL schema.
-- Section 1 is POSTGRES_READY/DDL.sql from the FROZEN Phase 3, inlined byte for
-- byte. Phase 4 does not redesign the data model.
--   source : BIS_SIH26107_DATA/POSTGRES_READY/DDL.sql
--   sha256 : 23df8be0da588a6b709e8d5d94afc96f178c132194b2e7ef8adb52870246c675
-- Section 2 adds read-only views only, so the Phase-4 spec's plain table names
-- resolve without duplicating a single row.
-- Objects live in schema "bis", not "public": Supabase does not expose bis
-- through its auto-generated REST API, so loading data creates no public surface.

-- ===================== SECTION 1: FROZEN PHASE-3 DDL =====================
-- BIS SIH26107 - PHASE 3 canonical layer, PostgreSQL DDL
-- Generated by p3_build.py. Every table maps 1:1 to a canonical CSV that
-- stays in place under BIS_SIH26107_DATA/; nothing is duplicated here, so
-- there is exactly one source of truth per table.
-- Empty CSV fields load as NULL. A NULL means 'not established by the
-- uploaded data' - the reason is in record_provenance.missing_reason.
CREATE SCHEMA IF NOT EXISTS bis;
SET search_path TO bis, public;

DROP TABLE IF EXISTS is_master CASCADE;
CREATE TABLE is_master (
    is_id                              text PRIMARY KEY,
