    iec_reference                      text,
    part_source                        text,
    is_iec_flag                        text,
    title                              text,
    title_vernacular                   text,
    standard_scope                     text,
    part_section_label                 text,
    revision                           text,
    version                            text,
    publication_date                   text,
    publication_date_precision         text,
    revision_date                      text,
    reaffirmation_review_date          text,
    standard_status                    text,
    standard_status_original           text,
    superseded_standard                text,
    superseding_standard               text,
    technical_committee                text,
    subcommittee                       text,
    product_category                   text,
    degree_of_equivalence              text,
    mandatory_voluntary                text,
    certification_type                 text,
    official_url                       text,
    document_url                       text,
    source_url                         text,
    source_reference_label             text,
    parse_status                       text,
    source_file_count                  integer,
    source_file_ids                    text,
    source_files                       text,
    source_sheets                      text,
    source_rows                        text,
    record_disposition                 text,
    conflict_count                     integer,
    conflict_fields                    text,
    review_flag                        text,
    review_reason                      text,
    populated_field_count              integer,
    completeness_pct                   numeric
);

