    quarantine_id TEXT,
    origin_table TEXT,
    relationship_id TEXT,
    relationship_type TEXT,
    resolved_side_entity_type TEXT,
    resolved_side_entity_id TEXT,
    resolved_side_label TEXT,
    unresolved_side_role TEXT,
    unresolved_side_reference TEXT,
    evidence_column TEXT,
    evidence_value TEXT,
