    source_file TEXT,
    source_sheet TEXT,
    source_row TEXT,
    quarantine_reason TEXT,
    retained_in TEXT,
    confidence TEXT,
    PRIMARY KEY (quarantine_id)
);


-- ===================== SECTION 2: PHASE-4 ALIAS VIEWS ====================
-- Names used by the Phase-4 smoke tests. A view is not a copy: one source of
-- truth per table is preserved.
CREATE OR REPLACE VIEW bis.standards AS SELECT * FROM bis.is_master;
CREATE OR REPLACE VIEW bis.products AS SELECT * FROM bis.product_master;
CREATE OR REPLACE VIEW bis.qcos AS SELECT * FROM bis.qco_master;
