CREATE OR REPLACE VIEW bis.documents AS SELECT * FROM bis.document_master;
CREATE OR REPLACE VIEW bis.product_manuals AS SELECT * FROM bis.product_manual_master;
CREATE OR REPLACE VIEW bis.tests AS SELECT * FROM bis.test_master;
CREATE OR REPLACE VIEW bis.labs AS SELECT * FROM bis.lab_master;
CREATE OR REPLACE VIEW bis.faq AS SELECT * FROM bis.faq_master;
CREATE OR REPLACE VIEW bis.notifications AS SELECT * FROM bis.notification_master;
CREATE OR REPLACE VIEW bis.legal AS SELECT * FROM bis.legal_master;
CREATE OR REPLACE VIEW bis.hallmarking AS SELECT * FROM bis.hallmarking_master;
CREATE OR REPLACE VIEW bis.fmcs AS SELECT * FROM bis.fmcs_master;

